import numpy as np
from robot import tools, handoff
from ora_lib import Direction, Point, object_geometry

TABLE_Z = 0.7655
LINK6_TO_JAW = 0.1501
PAD_HALF_GAP = 0.0045
ARMBASE = {"left": np.array([-0.2995, -0.3523]), "right": np.array([0.3005, -0.3523])}
HOME = {"left": np.array([-0.2995290756225586, -0.35229986906051636, 0.921500027179718]),
        "right": np.array([0.3004709482192993, -0.35229986906051636, 0.921500027179718])}

def unit(v):
    v = np.asarray(v, dtype=float)
    return v / np.linalg.norm(v)

def measure_bowls(cam="head"):
    r = tools.vision_ground(camera=cam, text="bowl", max_candidates=3)
    out = []
    for c in r["result"]["candidates"]:
        g = object_geometry(c)
        mn = np.array(g.aabb_min_xyz_m); mx = np.array(g.aabb_max_xyz_m)
        out.append(dict(ref=c["target_ref"], cand=c["candidate_id"],
                        axis_xy=np.array([(mn[0]+mx[0])/2, (mn[1]+mx[1])/2]),
                        center=np.array(g.center_xyz_m), aabb_min=mn, aabb_max=mx,
                        support=g.support_z_m, height=g.height_above_support_m,
                        extent=np.array(g.extent_xyz_m), status=g.status))
    return out

def nearest(bowls, xy):
    xy = np.asarray(xy, dtype=float)
    return min(bowls, key=lambda b: float(np.linalg.norm(b["axis_xy"] - xy)))

def rim_grasp_flange(bowl, arm, dz_pad=-0.005, lift=0.0):
    """flange world position for a vertical rim pinch on the side of the bowl nearest the arm base."""
    u = unit(ARMBASE[arm] - bowl["axis_xy"])
    r_out = float(bowl["extent"][0] + bowl["extent"][1]) / 4.0
    rim_xy = bowl["axis_xy"] + r_out * u
    rim_z = bowl["aabb_max"][2]
    flange = np.array([rim_xy[0], rim_xy[1], rim_z + dz_pad + LINK6_TO_JAW + lift])
    return flange, u, r_out

def vert_point(xyz):
    return Point([float(x) for x in xyz], "world")

def down_dir():
    return Direction([0.0, 0.0, -1.0], "world")

def jaw_dir(u):
    return Direction([float(-u[0]), float(-u[1]), 0.0], "world")

def check(r, what, tol=None):
    print(f"[{what}] ok={r.ok} status={r.status} failure={r.failure_code} err_m={r.target_error_m} cut={r.cut_short}")
    if not r.ok:
        handoff(f"{what} failed", status=r.status, failure=r.failure_code, summary=r.summary)
    return r
